using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Autodesk.Revit.DB;using Autodesk.Revit.UI;using Autodesk.Revit.UI.Events;
namespace SantaRosaWebExport3 {
public class App:IExternalApplication{bool done;ExternalEvent ev;public Result OnStartup(UIControlledApplication a){a.Idling+=Run;return Result.Succeeded;}public Result OnShutdown(UIControlledApplication a){a.Idling-=Run;return Result.Succeeded;}void Run(object s,IdlingEventArgs e){if(done||!File.Exists(@"D:\trabajos\Costos\Estructura Metalica\ExportWeb3.trigger"))return;done=true;ev=ExternalEvent.Create(new Handler());ev.Raise();}}
public class Handler:IExternalEventHandler{
const string root=@"D:\trabajos\Costos\Estructura Metalica\SantaRosa_Coordinador";public string GetName(){return "Exportar modelo web con metrados sin modificar Revit";}
IEnumerable<Solid> Solids(GeometryElement ge){foreach(var g in ge){if(g is Solid s&&s.Volume>1e-10)yield return s;else if(g is GeometryInstance ins)foreach(var ss in Solids(ins.GetInstanceGeometry()))yield return ss;}}
string Kind(string n,string mark){if(n.StartsWith("Perno "))return "pernos";if(n.StartsWith("Anclaje "))return "anclajes";if(n.Contains("aranda")||mark.StartsWith("BA-"))return "barandas";if(mark.StartsWith("BR-"))return "brazos";if(mark.Length>3&&mark[0]=='R'&&char.IsDigit(mark[1]))return "rejilla";if(n.Contains("Grating")||mark.StartsWith("GR-"))return "grating";if(mark.StartsWith("BC-"))return "drenaje";if(n.Contains("Viga "))return "vigas";if(n.Contains("Apoyo")||n.Contains("tubular"))return "apoyos";if(n.Contains("soldadura"))return "soldaduras";if(n.Contains("Placa")||n.Contains("union"))return "placas";return "otros";}
public void Execute(UIApplication ui){string stage="inicio";try{stage="documento activo";var d=ui.ActiveUIDocument.Document;if(!d.PathName.EndsWith("SantaRosaII_Rejilla_DETALLADO_CORREGIDO.rvt",StringComparison.OrdinalIgnoreCase))throw new Exception("Activar archivo final CORREGIDO");Directory.CreateDirectory(root);var objects=new List<object>();int triangles=0;foreach(var e in new FilteredElementCollector(d).OfClass(typeof(DirectShape)).Cast<DirectShape>().OrderBy(e=>e.Id.Value)){stage=e.Name+" ID="+e.Id.Value;var ss=Solids(e.get_Geometry(new Options{DetailLevel=ViewDetailLevel.Fine})).ToList();var pos=new List<float>();var materialAreas=new Dictionary<string,double>();foreach(var s in ss)foreach(Face face in s.Faces){if(face==null)continue;var material=(d.GetElement(face.MaterialElementId) as Material)?.Name??"Sin clasificar";if(!materialAreas.ContainsKey(material))materialAreas[material]=0;materialAreas[material]+=face.Area;var mesh=face.Triangulate(.3);if(mesh==null)continue;for(int i=0;i<mesh.NumTriangles;i++){var tr=mesh.get_Triangle(i);for(int j=0;j<3;j++){var p=tr.get_Vertex(j);pos.Add((float)Math.Round(p.X*.3048,5));pos.Add((float)Math.Round(p.Z*.3048,5));pos.Add((float)Math.Round(-p.Y*.3048,5));}triangles++;}}
string mat=materialAreas.OrderByDescending(x=>x.Value).Select(x=>x.Key).FirstOrDefault()??"Sin clasificar",mark=e.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).AsString()??"",kind=Kind(e.Name,mark);bool inox=mat.Contains("AISI304"),galv=mat.ToLower().Contains("galvan"),fast=kind=="pernos"||kind=="anclajes";double volume=ss.Sum(s=>s.Volume)*.028316846592,area=ss.Sum(s=>s.SurfaceArea)*.09290304,density=inox?7930:7850;var materialObj=d.GetElement(ss.SelectMany(s=>s.Faces.Cast<Face>()).OrderByDescending(f=>f.Area).Select(f=>f.MaterialElementId).FirstOrDefault()??ElementId.InvalidElementId) as Material;stage+=" color";var color=materialObj?.Color;string hex=color==null?"#8396a6":"#"+color.Red.ToString("X2")+color.Green.ToString("X2")+color.Blue.ToString("X2");objects.Add(new{id=e.UniqueId,revitId=e.Id.Value,mark,name=e.Name,kind,material=mat,color=hex,volume,area,weight=volume*density,density,paint=(!inox&&!galv&&!fast&&kind!="soldaduras")?"revisar":"excluido",boltDiameter=fast?System.Text.RegularExpressions.Regex.Match(e.Name,@"M\d+").Value:"",notes=e.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).AsString()??"",positions=pos});}
stage="serializar proyecto";var project=new{format="srii-coordinator",version=1,projectId=d.ProjectInformation.UniqueId,revision=File.GetLastWriteTimeUtc(d.PathName).ToString("o"),exportedAt=DateTime.UtcNow.ToString("o"),name="Santa Rosa II · Estructura metálica",source=Path.GetFileName(d.PathName),units=new{length="m",area="m²",volume="m³",weight="kg"},criteria=new{weight="Volumen geométrico × densidad adoptada: acero7850 kg/m³; AISI3047930 kg/m³. Revisar clasificación y densidades.",area="Superficie geométrica total de sólidos, incluyendo caras de contacto e interiores. No representa automáticamente pintura neta.",paint="Tratamiento pendiente de confirmación. Inox y elementos identificados como galvanizados excluidos inicialmente. Clasificación por material y nombre, editable en visor.",fasteners="Cada elemento de perno/anclaje representa un conjunto:1 perno,1 tuerca,2 arandelas; desglose según geometría del generador. Verificar con especificación.",source="Extracción de DirectShapes del archivo final, sin modificar el modelo. El estado de obra se registra en el visor y no se escribe en Revit."},objects};string file=Path.Combine(root,"SantaRosa_Modelo.srii");File.WriteAllText(file,JsonSerializer.Serialize(project));File.WriteAllText(Path.Combine(root,"Exportacion_ok.txt"),"Modelo: "+d.PathName+"\nElementos="+objects.Count+"\nTriangulos="+triangles+"\nExportado="+file+"\nModelo Revit sin modificar.");}catch(Exception ex){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"Exportacion_error.txt"),stage+"\n"+ex.ToString());}}
}}


